      tiop->tchars.t_stopc = -1; /* C-s */
      tiop->tchars.t_startc = -1; /* C-q */

      /* If there is an XON character, bind it to restart the output. */
      if (oldtio.tchars.t_startc != -1)
	rl_bind_key (oldtio.tchars.t_startc, rl_restart_output);
